<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Holder\UserWellcomeAtAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWellcomeAtAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserWellcomeAtAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getWellcomeAt returns null on a freshly created holder.
     */
    public function testWellcomeAtNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserWellcomeAtAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isWellcomeAtAssigned());
        $this->assertNull($holder->getWellcomeAt());
    }
}
class ImplWithUserWellcomeAtAttributeHolderUnitTest
{
    use UserWellcomeAtAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedWellcomeAtRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultWellcomeAt();
    }
}
